-- Run as a local administrator in FREEPDB1, before updated services start.
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
ALTER SESSION SET CONTAINER=FREEPDB1;
DECLARE n NUMBER;BEGIN
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='CF_AUTH' AND TABLE_NAME='CF_LENDER_REGISTRY';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CF_AUTH.CF_LENDER_REGISTRY(LENDER_ID VARCHAR2(36) PRIMARY KEY REFERENCES CF_AUTH.CF_ORGANIZATIONS(ORGANIZATION_ID),LENDER_CODE VARCHAR2(20) UNIQUE NOT NULL,LENDER_TYPE VARCHAR2(10) CHECK(LENDER_TYPE IN (''BANK'',''NBFC'')) NOT NULL,ADAPTER VARCHAR2(20) CHECK(ADAPTER IN (''BANK_A'',''NBFC_B'',''BANK_C'')) NOT NULL,CREATED_BY VARCHAR2(100) NOT NULL,CREATION_REASON VARCHAR2(450 CHAR) NOT NULL,CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)'; END IF;
 SELECT COUNT(*) INTO n FROM ALL_TABLES WHERE OWNER='CF_ELIGIBILITY' AND TABLE_NAME='CF_ROUTING_LOCK';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CF_ELIGIBILITY.CF_ROUTING_LOCK(LOCK_ID NUMBER PRIMARY KEY CHECK(LOCK_ID=1))';END IF;
END;
/
MERGE INTO CF_ELIGIBILITY.CF_ROUTING_LOCK T USING(SELECT 1 ID FROM DUAL) S ON(T.LOCK_ID=S.ID) WHEN NOT MATCHED THEN INSERT(LOCK_ID) VALUES(S.ID);
MERGE INTO CF_AUTH.CF_LENDER_REGISTRY T USING (
 SELECT ORGANIZATION_ID ID,CASE SUBSTR(ORGANIZATION_ID,-1) WHEN '1' THEN 'bank-a' WHEN '2' THEN 'nbfc-b' ELSE 'bank-c' END CODE,
 CASE SUBSTR(ORGANIZATION_ID,-1) WHEN '2' THEN 'NBFC' ELSE 'BANK' END TYPE,
 CASE SUBSTR(ORGANIZATION_ID,-1) WHEN '1' THEN 'BANK_A' WHEN '2' THEN 'NBFC_B' ELSE 'BANK_C' END ADAPTER
 FROM CF_AUTH.CF_ORGANIZATIONS WHERE ORGANIZATION_ID IN('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb2','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb3')
) S ON(T.LENDER_ID=S.ID) WHEN NOT MATCHED THEN INSERT(LENDER_ID,LENDER_CODE,LENDER_TYPE,ADAPTER,CREATED_BY,CREATION_REASON) VALUES(S.ID,S.CODE,S.TYPE,S.ADAPTER,'system-migration','Register existing lender integration without changing its accounts or applications');
GRANT SELECT ON CF_AUTH.CF_LENDER_REGISTRY TO CF_LENDER_INTEGRATION,CF_SIM_BANK_A,CF_CONSENT;
GRANT SELECT,UPDATE ON CF_ELIGIBILITY.CF_ROUTING_LOCK TO CF_AUTH;
GRANT SELECT,INSERT ON CF_ELIGIBILITY.LENDER_PRODUCT_RULE TO CF_AUTH;
GRANT SELECT,INSERT ON CF_ELIGIBILITY.LENDER_PRODUCT_HEAD TO CF_AUTH;
GRANT INSERT ON CF_ELIGIBILITY.LENDER_PRODUCT_PURPOSE TO CF_AUTH;
GRANT INSERT ON CF_ELIGIBILITY.LENDER_RULE_CHANGE TO CF_AUTH;
COMMIT;
-- Normalize pre-existing duplicate/gapped positions using their current order.
DECLARE n NUMBER;v NUMBER;BEGIN
 SELECT LOCK_ID INTO n FROM CF_ELIGIBILITY.CF_ROUTING_LOCK WHERE LOCK_ID=1 FOR UPDATE;
 FOR r IN(SELECT R.*,ROW_NUMBER() OVER(ORDER BY R.ROUTING_PRIORITY,R.PRODUCT_ID) ROUTING_POSITION FROM CF_ELIGIBILITY.LENDER_PRODUCT_RULE R JOIN CF_ELIGIBILITY.LENDER_PRODUCT_HEAD H ON H.PRODUCT_ID=R.PRODUCT_ID AND H.CURRENT_VERSION=R.RULE_VERSION) LOOP
  IF r.ROUTING_PRIORITY<>r.ROUTING_POSITION THEN
   v:=r.RULE_VERSION+1;
   INSERT INTO CF_ELIGIBILITY.LENDER_PRODUCT_RULE(PRODUCT_ID,RULE_VERSION,LENDER_ID,PRODUCT_NAME,MIN_AGE_MONTHS,MIN_AVERAGE_NET,MAX_RETURN_PERCENT,MIN_AMOUNT,MAX_AMOUNT,SALES_MULTIPLIER,ROUTING_PRIORITY,ACTIVE,MIN_CREDIT_SCORE_BAND,MAX_REPAYMENT_PERCENT,ASSESSMENT_APR_PERCENT)
   SELECT PRODUCT_ID,v,LENDER_ID,PRODUCT_NAME,MIN_AGE_MONTHS,MIN_AVERAGE_NET,MAX_RETURN_PERCENT,MIN_AMOUNT,MAX_AMOUNT,SALES_MULTIPLIER,r.ROUTING_POSITION,ACTIVE,MIN_CREDIT_SCORE_BAND,MAX_REPAYMENT_PERCENT,ASSESSMENT_APR_PERCENT FROM CF_ELIGIBILITY.LENDER_PRODUCT_RULE WHERE PRODUCT_ID=r.PRODUCT_ID AND RULE_VERSION=r.RULE_VERSION;
   INSERT INTO CF_ELIGIBILITY.LENDER_PRODUCT_PURPOSE(PRODUCT_ID,RULE_VERSION,PURPOSE) SELECT PRODUCT_ID,v,PURPOSE FROM CF_ELIGIBILITY.LENDER_PRODUCT_PURPOSE WHERE PRODUCT_ID=r.PRODUCT_ID AND RULE_VERSION=r.RULE_VERSION;
   INSERT INTO CF_ELIGIBILITY.LENDER_RULE_CHANGE(PRODUCT_ID,RULE_VERSION,ACTOR_ID,REASON,RETRY_KEY,REQUEST_HASH) VALUES(r.PRODUCT_ID,v,'system-migration','[ADMIN_ROUTING] Normalize existing positions to enforce unique ordered routing','routing-migration:'||r.PRODUCT_ID||':'||v,STANDARD_HASH('routing-migration','SHA256'));
   UPDATE CF_ELIGIBILITY.LENDER_PRODUCT_HEAD SET CURRENT_VERSION=v WHERE PRODUCT_ID=r.PRODUCT_ID;
  END IF;
 END LOOP;
 COMMIT;
END;
/
EXIT
